<script setup>
import { computed, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { useLearning, percent } from '../store'
const store = useLearning(), route = useRoute(), router = useRouter()
const selected = ref(route.query.node || '')
const current = computed(() => store.nodes.find(n => n.id === selected.value))
const chapters = computed(() => [...new Set(store.nodes.map(n => n.chapter))])
</script>
<template>
  <div class="page-heading"><div><p class="eyebrow">函数与导数 · 完整学习路径</p><h1>{{ route.path === '/levels' ? '把理解，变成每一步成就' : '找到知识之间的连接' }}</h1><p>每个节点独立评估；连线以先修知识点说明呈现，支持多个先修。</p></div><div class="legend"><span>○ 未评估</span><span>◐ 学习中</span><span>● 已通过</span></div></div>
  <div class="knowledge-layout"><div class="knowledge-tree"><section v-for="chapter in chapters" :key="chapter" class="knowledge-chapter"><h2>{{ chapter }}</h2><div class="node-grid"><button v-for="n in store.nodes.filter(n => n.chapter === chapter)" :key="n.id" class="knowledge-node" :class="{selected: selected === n.id, passed:n.passed_at, locked:!n.available}" @click="selected = n.id" :data-testid="`node-${n.id}`"><div><strong>{{ n.name }}</strong><span class="badge" :class="{'success':n.status === '已通过', 'warning':n.status === '建议复习'}">{{ n.status }}</span></div><p>{{ n.prerequisites.length ? '先修：' + n.prerequisites.map(store.name).join(' + ') : '学习起点 · 无先修要求' }}</p><div class="progress-track"><i :style="{width: `${(n.mastery || 0)*100}%`}"></i></div><small>{{ percent(n.mastery) }} · {{ n.samples }} 条有效样本 <span v-if="!n.available">· 待补齐先修</span></small></button></div></section></div><aside class="knowledge-detail"><template v-if="current"><p class="eyebrow">{{ current.chapter }} / {{ current.id }}</p><h2>{{ current.name }}</h2><p>{{ current.description }}</p><div class="large-mastery">{{ percent(current.mastery) }}</div><p>{{ current.samples }} 条有效记录 · {{ current.distinct_count }} 道不同题目</p><h3>必要先修</h3><button v-for="p in current.prerequisites" :key="p" class="prereq-link" @click="selected=p">{{ store.name(p) }} <span>{{ current.missing_prerequisites.includes(p) ? '需要巩固' : '已满足' }}</span></button><p v-if="!current.prerequisites.length">无先修要求，可以直接开始。</p><p v-if="current.passed_at" class="success-text">历史成就已保留：{{ current.passed_at.slice(0,10) }}</p><button class="primary wide" @click="router.push(`/practice?knowledge=${current.id}`)">练习这个知识点</button><RouterLink class="text-button wide" :to="`/assistant?knowledge=${current.id}`">向 AI 提问</RouterLink><small>自定义练习可用于提前诊断；闯关通过仍需满足所有先修要求。</small></template><template v-else><div class="node-placeholder">⌘</div><h2>选择一个知识点</h2><p>查看它的掌握状态、先修缺口和下一步练习。</p></template><div class="rule-note">通关条件：最近 {{ store.rules.window }} 条有效记录内至少 {{ store.rules.pass_distinct }} 道不同题目，掌握度 ≥ {{ percent(store.rules.pass_mastery) }}，且所有必要先修当前通过。历史成就不会因后续答错而删除。</div></aside></div>
</template>
